import type { ParsedSaveSource, ResumeMessage } from './types';
import { isRecoverableStat } from './migrations';
import { extractAcuTables } from './acuTables';
export const MAX_SAVE_BYTES=128*1024*1024; const MAX_RESUME_CHARS=12_000; const MAX_MEDIA_URI=256*1024;
function rejectOversizedEmbeddedMedia(raw:string):void{let cursor=0;while((cursor=raw.indexOf('data:',cursor))!==-1){const comma=raw.indexOf(',',cursor+5);if(comma===-1){cursor+=5;continue}let end=comma+1;while(end<raw.length&&!/[\s"']/.test(raw[end]))end++;if(end-comma-1>MAX_MEDIA_URI)throw new Error(`存档含超过 ${Math.floor(MAX_MEDIA_URI/1024)} KiB 的内嵌 data URI，请先移除媒体后再导入`);cursor=end}}
function cleanVisibleText(raw:unknown):string{let text=typeof raw==='string'?raw:'';return text.replace(/<UpdateVariable>[\s\S]*?<\/UpdateVariable>/gi,'').replace(/<JSONPatch>[\s\S]*?<\/JSONPatch>/gi,'').replace(/<opening_setup\b[\s\S]*?<\/opening_setup>/gi,'').replace(/<counterfeit_resume_capsule\b[\s\S]*?<\/counterfeit_resume_capsule>/gi,'').replace(/<OpeningUI\s*\/>/gi,'').replace(/<think(?:ing)?>[\s\S]*?<\/think(?:ing)?>/gi,'').replace(/```(?:tool|json)?[\s\S]*?```/gi,m=>m.length>2000?'[已移除工具或媒体内容]':m).replace(/data:[^;\s]+;base64,[A-Za-z0-9+/=]+/g,'[已移除内嵌媒体]').replace(/<[^>]+>/g,'').trim().slice(0,MAX_RESUME_CHARS)}
function activeVariables(record:any):any[]{const found:any[]=[];const push=(v:any)=>{if(v&&typeof v==='object')found.push(v)};push(record?.variables);const swipe=Number.isInteger(record?.swipe_id)?record.swipe_id:Number.isInteger(record?.swipe_index)?record.swipe_index:0;if(Array.isArray(record?.variables))push(record.variables[swipe]);else if(record?.variables&&typeof record.variables==='object')push(record.variables[String(swipe)]);if(Array.isArray(record?.swipe_info))push(record.swipe_info[swipe]?.variables);else if(record?.swipe_info&&typeof record.swipe_info==='object')push(record.swipe_info[String(swipe)]?.variables);push(record?.swipes?.[swipe]?.variables);return found}
function fullStat(candidate:any):Record<string,any>|null{const stat=candidate?.stat_data??candidate?.variables?.stat_data;if(!stat||typeof stat!=='object'||Array.isArray(stat)||!('mode'in stat)||!('current_scene'in stat)||!('world'in stat))return null;return JSON.parse(JSON.stringify(stat))}
async function digest(file:File):Promise<string>{const hash=await crypto.subtle.digest('SHA-256',await file.arrayBuffer());return[...new Uint8Array(hash)].map(v=>v.toString(16).padStart(2,'0')).join('')}
function parseRecords(records:any[],source:ParsedSaveSource['source'],sha256:string,warnings:string[]):ParsedSaveSource{const header=records[0];if(!header||typeof header!=='object'||(!('user_name'in header)&&!('name'in header)&&!('chat_metadata'in header)))throw new Error('缺少 SillyTavern 聊天头');if(header.is_group||header.group_id||header.chat_metadata?.group_id||header.chat_metadata?.members)throw new Error('暂不支持群聊存档');const meta=header.chat_metadata??{};const declared={declaredCampaignId:meta.campaign_id??null,declaredCampaignRevision:Number.isInteger(meta.campaign_revision)?meta.campaign_revision:null};let recovered:Record<string,any>|null=null;let recoveredFloor:number|null=null;const tail:ResumeMessage[]=[];for(let i=records.length-1;i>=1&&!recovered;i--)for(const vars of activeVariables(records[i])){const stat=fullStat(vars);if(!stat)continue;if(isRecoverableStat(stat,declared)){recovered=stat;recoveredFloor=i-1;break}warnings.push(`楼层 ${i-1} 的最新完整快照不兼容，继续向前回退`)}if(!recovered)throw new Error('没有找到可恢复的合法 stat_data 快照');for(const record of records.slice(1)){const role=record?.is_user===true||record?.role==='user'?'user':record?.role==='assistant'||record?.is_user===false?'assistant':null;if(!role)continue;const text=cleanVisibleText(record.mes??record.message??record.text);if(text)tail.push({role,text})}let chars=0;const resumeTail:ResumeMessage[]=[];for(const item of tail.slice(-8).reverse()){if(chars+item.text.length>MAX_RESUME_CHARS)continue;resumeTail.unshift(item);chars+=item.text.length}return{source,cardVersion:meta.card_version??null,schemaVersion:Number.isInteger(meta.counterfeit_save_schema_version)?meta.counterfeit_save_schema_version:null,...declared,statData:recovered,resumeTail,messageCount:records.length-1,recoveredFloor,warnings,sha256,tableSheets:extractAcuTables(meta)}}
export async function parseChatExport(file:File):Promise<ParsedSaveSource>{if(file.size>MAX_SAVE_BYTES)throw new Error('文件超过128 MiB限制');const sha256=await digest(file);const first=(await file.slice(0,4096).text()).trimStart()[0];if(first==='['){const raw=await file.text();rejectOversizedEmbeddedMedia(raw);const parsed=JSON.parse(raw);if(!Array.isArray(parsed))throw new Error('JSON聊天导出必须是数组');return parseRecords(parsed,'sillytavern-json',sha256,[])}const reader=file.stream().getReader();const decoder=new TextDecoder();let buffer='';const records:any[]=[];const warnings:string[]=[];while(true){const{value,done}=await reader.read();buffer+=decoder.decode(value,{stream:!done});const lines=buffer.split(/\r?\n/);buffer=lines.pop()??'';for(const line of lines){if(!line.trim())continue;rejectOversizedEmbeddedMedia(line);try{records.push(JSON.parse(line))}catch{throw new Error(`JSONL第${records.length+1}行损坏`)}}if(done)break}if(buffer.trim())try{rejectOversizedEmbeddedMedia(buffer);records.push(JSON.parse(buffer))}catch(error){if(error instanceof Error&&error.message.includes('data URI'))throw error;warnings.push('末行截断，已忽略')}return parseRecords(records,'sillytavern-jsonl',sha256,warnings)}
